class Solution {
public:
    long long countPairs(vector<string>& words) {
        unordered_map<string,long long> freq;
        long long ans=0;
        for(const string &s:words){
            string key;
            for(int i=1;i<(int)s.size();++i)
                key+=char('a'+(s[i]-s[i-1]+26)%26);
            key+='#';
            ans+=freq[key]++;
        }
        return ans;
    }
};
